/* Content-grounded showcase guide. Local retrieval, no model/API call. */
(()=>{'use strict';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const onApp=location.pathname.includes('/apps/'),prefix=onApp?'../':'',slug=p=>p.name.toLowerCase().replaceAll(' ','-');
const aliases=[['rfp','proposal','bid','tender'],['webinar','cadence','campaign','email follow up'],['triage','qualification','qualify','lead scoring','routing leads'],['simulation','persona','focus group','message testing'],['budget','department spending'],['sales dashboard','pipeline','sales performance','revenue'],['allocation','staffing','capacity','skills','workload'],['collaboration','contractor','workspace','project files'],['insights','reports','reporting','insite'],['forecast','projection','growth scenario'],['roi','payback','return on investment'],['tracker','milestone','project status'],['nightwatch','prospecting','linkedin','overnight'],['client health','renewal','retention','account risk'],['fp&a','variance','actuals','financial'],['business case','investment case'],['impact','adoption','ai value'],['profitability','margin','contribution'],['tech support','technical support','support email','customer support'],['knowledge','policy','policies','internal questions','manuals'],['operations agent','request','approvals','intake']];
let history=[],context=[];try{const saved=JSON.parse(sessionStorage.getItem('nine67-guide-chat')||'null');if(saved){history=saved.history.slice(-20);context=saved.context||[]}}catch(e){}
let opened=false;const host=document.createElement('div');host.id='nine67-chat';document.body.appendChild(host);
const starter=['Which application fits my team?','How do you work with our people?','What is real in these demos?'];
function remember(){try{sessionStorage.setItem('nine67-guide-chat',JSON.stringify({history,context}))}catch(e){}}
function currentProject(){if(onApp)return Number(document.body.dataset.app);return typeof current==='number'&&current>=0?current:null}
function write(){host.innerHTML=`<button class="n67-chat-launch" aria-label="Ask Nine-67 about these applications" aria-expanded="${opened}" onclick="Nine67Guide.toggle()"><img class="n67-chat-orbit" src="${prefix}nine67-logo.png" alt=""><span>Ask Nine-67</span>${opened?'−':'+'}</button>${opened?`<section class="n67-chat-panel" role="dialog" aria-label="Ask Nine-67 application guide"><header><div><span>NINE-67 / APPLICATION GUIDE</span><h2>What could AI do for your team?</h2></div><button onclick="Nine67Guide.toggle()" aria-label="Close application guide">×</button></header><div class="n67-chat-log" role="log" aria-live="polite">${history.length?history.map(m=>m.role==='user'?`<div class="n67-chat-question">${safe(m.text)}</div>`:answerHTML(m.answer)).join(''):`<div class="n67-chat-answer"><p>I can help you explore all 21 applications, compare workflows, understand the AI, and prepare for an implementation conversation.</p><p>Tell me what your team spends time doing, or choose a question below.</p></div>`}</div><div class="n67-chat-prompts">${(history.length?['How would this fit our team?','What information would we need?','Show all applications']:starter).map(q=>`<button data-question="${safe(q)}">${safe(q)}</button>`).join('')}</div><form id="n67-chat-form"><label class="n67-sr-only" for="n67-chat-input">Ask about Nine-67 applications</label><textarea id="n67-chat-input" placeholder="What is your team trying to improve?" rows="2" maxlength="1500" required></textarea><button type="submit" aria-label="Send question">↑</button></form><footer>Answers from showcase content · No live AI model<br>No uploads or client data needed. <button onclick="Nine67Guide.clear()">Clear chat</button></footer></section>`:''}`;
if(!opened)return;host.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.question)));host.querySelectorAll('[data-project-link]').forEach(b=>b.addEventListener('click',()=>openProject(Number(b.dataset.projectLink))));host.querySelector('#n67-chat-form').addEventListener('submit',e=>{e.preventDefault();ask(host.querySelector('#n67-chat-input').value)});host.querySelector('#n67-chat-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask(e.target.value)}});const processLink=host.querySelector('.n67-process-link');if(processLink&&!onApp)processLink.addEventListener('click',e=>{e.preventDefault();opened=false;write();openProcessPage()});const log=host.querySelector('.n67-chat-log');log.scrollTop=log.scrollHeight;}
function answerHTML(a){return `<div class="n67-chat-answer">${a.title?`<h3>${safe(a.title)}</h3>`:''}${a.sections.map(s=>`<div>${s.title?`<b>${safe(s.title)}</b>`:''}<p>${safe(s.text)}</p></div>`).join('')}${a.links?.length?`<div class="n67-chat-sources"><span>EXPLORE THE SOURCE</span>${a.links.map(i=>`<button data-project-link="${i}">${safe(CLIENT_PROJECTS[i].name)} →</button>`).join('')}</div>`:''}${a.process?`<a class="n67-process-link" href="${prefix}#our-process">Our process & technology →</a>`:''}</div>`}
function result(title,sections,links=[],process=false){return {title,sections,links,process}}
function findProjects(q){const clean=q.toLowerCase();return CLIENT_PROJECTS.map((p,i)=>{let score=clean.includes(p.name.toLowerCase())?25:0;for(const term of aliases[i])if(clean.includes(term))score+=term.includes(' ')?8:5;return {i,score}}).filter(x=>x.score>=5).sort((a,b)=>b.score-a.score)}
function answer(question){const q=question.toLowerCase(),found=findProjects(q);let ids=found.filter(x=>x.score>=Math.max(5,(found[0]?.score||0)*.5)).slice(0,3).map(x=>x.i);const here=currentProject();
if(!ids.length&&/this|these|it |our team|information|data|integrat|connect|measure|start|people|cost|timeline/.test(q))ids=context.length?context:(here!==null?[here]:[]);
if(/price|pricing|how much|cost to build|how long|timeline|weeks|months/.test(q)&&!(/roi|budget|forecast/.test(q)&&found.length)){return result('Scope comes before a quote',[{text:'The showcase does not publish implementation prices or delivery commitments. Scope depends on the workflow, integrations, data readiness, access requirements, and review needs.'},{title:'A useful first conversation',text:'Choose one workflow, identify who owns it, bring representative examples, and describe the result you need. Nine-67 can then agree the approach, participants, and milestones with you.'}],ids,true)}
if(/\breal\b|\blive\b|production|simulated|actually built|client names|case stud|proof|results|deploy/.test(q))return result('What you are seeing',[{text:'These are designed, interactive application examples using fictional records and simulated AI. You can inspect the interfaces, try workflow actions, and adjust supported sample inputs. This site does not establish a live client deployment or verified business outcome.'},{text:'A production project would connect approved data and services, define permissions and review controls, and be tested with the client team. Ask Nine-67 for relevant implementation evidence and references where available.'}],ids,true);
if(/secure|security|privacy|permission|pii|confidential|upload|compliance|gdpr|hipaa/.test(q))return result('Data access is part of the implementation design',[{text:'This showcase uses fictional sample information. Do not enter confidential client information. This chat guide runs locally in your browser and does not send messages to an AI API.'},{text:'For a live application, the team would agree approved sources, user roles, access scope, retention, review controls, and the client environment. The showcase does not establish security certification or regulatory compliance.'}],ids,true);
if(/automatic|automate|autonomous|send.*itself|human.*review|approval/.test(q)&&!found.length)return result('AI assistance with explicit review',[{text:'These demos illustrate AI preparing drafts, summaries, recommendations, and structured requests. Supported buttons change only the sample session. No external messages are sent and no business system is updated.'},{text:'For a live application, the workflow owner agrees which actions can run automatically, which require approval, and how exceptions are handled. The appropriate boundary depends on the action and its consequences.'}],ids,true);
if(/train|onboard|adoption/.test(q)&&!found.length)return result('Build adoption into delivery',[{text:'Representative users help shape and test the application. A focused pilot gives the team a practical way to learn the workflow, review AI outputs, and identify gaps before wider use.'},{text:'Nine-67 and the client agree onboarding, ownership, feedback, and success measures as part of the project scope. This showcase does not promise a fixed training package.'}],ids,true);
if(/all applications|list.*app|what.*build|overview|show.*applications/.test(q))return result('Explore the application collection',[{text:'The portfolio covers sales and proposals, customer support and knowledge, financial planning, reporting, client relationships, and operational delivery. Each project page explains the inputs, AI assistance, human review, and a guided example.'}],CLIENT_PROJECTS.map((_,i)=>i));
if(/process|work with|your team|implementation|resources|who.*involv|how.*start|first step/.test(q))return result('A focused build with your team',[{title:'1. Understand the work',text:'A business owner sets the outcome. People doing the work show current examples, handoffs, and exceptions. Together we agree a focused scope and baseline.'},{title:'2. Design, connect, and build',text:'Nine-67 leads design and engineering. IT and source owners help confirm approved access and integrations. Your users review something tangible and subject experts validate specialist answers.'},{title:'3. Test, launch, and improve',text:'The team tests complete workflows, agrees acceptance, and launches with a small group. Participants, estimated time, responsibilities, and review milestones are agreed before the build.'}],[],true);
if(/claude|openai|vercel|supabase|azure|sharepoint|teams|technology|tech stack|microsoft|tools/.test(q)&&!ids.length)return result('Technology selected around the workflow',[{text:'Claude API and OpenAI API can support reasoning, drafting, extraction, and conversation. Teams and SharePoint can support collaboration and approved source material. Azure, Supabase, and Vercel can support enterprise connections, data, and application delivery where appropriate.'},{text:'These are implementation options, not live connections in this demonstration. Every application does not require every tool. The client environment and requirements determine the combination.'}],[],true);
if(/connect|integrat|salesforce|hubspot|erp|crm|sap|calendar|email system/.test(q))return result('Connections depend on your systems',[{text:ids.length?ids.map(i=>CLIENT_PROJECTS[i].name+': '+CLIENT_PROJECTS[i].systems+'.').join('\n\n'):'A live application can be scoped around approved source systems and collaboration tools. Tell Nine-67 which systems hold the information and which actions the application would need.'},{text:'No integration is confirmed by this demo. Feasibility depends on API access, permissions, data quality, client policies, and the review requirements for each action.'}],ids,true);
if(ids.length){context=ids;const sections=ids.map(i=>{const p=CLIENT_PROJECTS[i];let text;if(/input|information|data|source|need.*provide/.test(q))text=p.inputs+' Potential connections: '+p.systems+'.';else if(/team|people|resource|involv/.test(q))text=p.team+'. The actual commitment is scoped around systems, complexity, and review milestones.';else if(/measure|value|benefit|success|save|outcome/.test(q))text='What we would measure: '+p.measure+'. '+p.output;else if(/try|demo|example|walk.*through/.test(q))text=p.scenario+': '+p.steps.map((s,n)=>(n+1)+'. '+s).join(' → ')+'. Open the project and choose Try guided demo.';else text=p.summary+' '+p.does+' '+p.output;return {title:p.name,text}});return result(ids.length>1?'How these applications differ':'How this application works',sections,ids)}
if(/which|recommend|fit|help.*team|where.*begin/.test(q)){context=[18,0,5];return result('Start with one recurring task',[{text:'If your team repeatedly searches past answers, explore Tech Support Agent. If it drafts responses to RFPs, try Proposal Builder. If leaders assemble sales reports, start with Sales Dashboard.'},{text:'Tell me what comes in, what someone does by hand, and what they need to produce. Useful details include the team, source information, and approval step.'}],[18,0,5]);}
return result('Let’s narrow that to your workflow',[{text:'I can answer from the application and process information in this showcase. I do not have external company information, live client records, or unlisted commercial commitments.'},{text:'Try naming an application, describing a task, or asking about inputs, AI assistance, team roles, integrations, or the guided demos. For an unanswered detail, bring the question to Nine-67.'}],[],true)}
function ask(q){q=String(q||'').trim().slice(0,1500);if(!q)return;const a=answer(q);history.push({role:'user',text:q},{role:'assistant',answer:a});history=history.slice(-20);remember();write();host.querySelector('#n67-chat-input')?.focus()}
function openProject(i){opened=false;write();if(!onApp&&typeof nav==='function')nav(i);else location.href=prefix+'#'+slug(CLIENT_PROJECTS[i])}
window.Nine67Guide={toggle(){opened=!opened;write();if(opened)host.querySelector('#n67-chat-input')?.focus()},clear(){history=[];context=[];remember();write()},ask,answer};write();
})();
